HYPEREDGES = [h for h in HYPEREDGES if all(m in NODE_IDS for m in h[2])]


def emit() -> dict:
    nodes = []
    for nid, label, ftype, sfile, rat in NODES:
        nodes.append({
            "id": nid,
            "label": label,
            "file_type": ftype,
            "source_file": sfile,
            "source_location": None,
            "source_url": None,
            "captured_at": None,
            "author": None,
            "contributor": None,
            "rationale": rat,
        })
    edges = []
    for s, t, rel, conf, score in EDGES:
        edges.append({
            "source": s, "target": t, "relation": rel,
            "confidence": conf, "confidence_score": score,
            "source_file": next((n[3] for n in NODES if n[0] == s), None),
            "source_location": None, "weight": 1.0,
        })
    # Anchors: semantic -> real AST node ids.
    anchored = 0
    for sid, labels in ANCHORS.items():
        if sid not in NODE_IDS:
            continue
        for lab in labels:
            key = re.sub(r"[^a-z0-9]+", "", lab.lower())
            for target in BY_LABEL.get(key, [])[:3]:
                edges.append({
                    "source": sid, "target": target, "relation": "references",
                    "confidence": "INFERRED", "confidence_score": 0.95,
                    "source_file": next((n[3] for n in NODES if n[0] == sid), None),
                    "source_location": None, "weight": 1.0,
                })
                anchored += 1
    hyper = []
    for hid, label, members, rel, conf, score in HYPEREDGES:
        hyper.append({
            "id": hid, "label": label, "nodes": members, "relation": rel,
            "confidence": conf, "confidence_score": score,
            "source_file": next((n[3] for n in NODES if n[0] == members[0]), None),
        })
    print(f"nodes={len(nodes)} edges={len(edges)} (anchored={anchored}) hyperedges={len(hyper)}")
    return {"nodes": nodes, "edges": edges, "hyperedges": hyper,
            "input_tokens": 0, "output_tokens": 0}


if __name__ == "__main__":
    frag = emit()
    out = ROOT / "semantic_fragment.json"
    out.write_text(json.dumps(frag, indent=1, ensure_ascii=False), encoding="utf-8")
    print("wrote", out, f"{out.stat().st_size/1024:.0f} KB")